import { parseFrontmatter } from '@/marketing/docs/content'
import { CATEGORIES, type CaseResult } from '@/app/lib/verification/types'
import indexJson from './data/index.json'

/** Generated by `src/app/lib/verification/generate.test.ts` (same shape as its `VerificationIndex`). */
export interface IndexRow {
  id: string; category: string; steps: { carapace: number; opensees: number }; worst: number; pass: boolean
  rtol: { value: number; why?: string; quantities?: string[] }; skip: { quantity: string; why: string }[]
  shot: { result?: string }; sources: string[]; ndm: number; elements: number; nodes: number; source: { file: string; line: number }
}
export interface Index { generated: string; pysees: { commit: string }; carapace: { commit: string; wasmSha256: string }; opensees: { package: string; version: string }; cases: IndexRow[] }
export const INDEX = indexJson as unknown as Index

export interface VerificationCasePage extends IndexRow { title: string; description: string; features: string[]; body: string; path: string; knownDifference: boolean }

const raw = import.meta.glob('./content/*.md', { query: '?raw', import: 'default', eager: true }) as Record<string, string>
const text = Object.fromEntries(Object.entries(raw).map(([f, src]) => [/([^/]+)\.md$/.exec(f)![1], src]))

/** Every case, in page order (by category, then as registered), with its description. */
export const CASE_PAGES: VerificationCasePage[] = CATEGORIES.flatMap((cat) => INDEX.cases.filter((c) => c.category === cat.id)).map((c) => {
  const { meta, body } = parseFrontmatter(text[c.id] ?? '')
  return { ...c, title: meta.title ?? c.id, description: meta.description ?? '', features: (meta.features ?? '').split(',').map((f) => f.trim()).filter(Boolean), body, path: `/verification/${c.id}`, knownDifference: !!c.rtol.why }
})
export const findCase = (id?: string) => CASE_PAGES.find((c) => c.id === id)
export const categoryTitle = (id: string) => CATEGORIES.find((c) => c.id === id)?.title ?? id
export const MISSING_DESCRIPTIONS = INDEX.cases.filter((c) => !text[c.id]).map((c) => c.id)

/** A case's measurements and plot data, loaded on demand (they are too big to ship with every page). */
const data = import.meta.glob(['./data/*.json', '!./data/index.json'], { import: 'default' }) as Record<string, () => Promise<CaseResult>>
export const loadCase = (id: string) => data[`./data/${id}.json`]?.() ?? Promise.reject(new Error(`no data for ${id}`))

export const PYSEES_REPO = 'https://github.com/jchatkinson/pysees'
export const CARAPACE_REPO = 'https://github.com/jchatkinson/carapace'
export const sourceUrl = (c: IndexRow) => `${PYSEES_REPO}/blob/${INDEX.pysees.commit}/${c.source.file}#L${c.source.line}`
export const carapaceUrl = (path: string) => `${CARAPACE_REPO}/blob/${INDEX.carapace.commit}/${path}`
export const shot = (id: string, kind: 'model' | 'result') => `/verification/${id}-${kind}.webp`

/** A relative difference for people: 1.1 × 10⁻⁶. */
export function sci(v: number, digits = 1): string {
  if (!Number.isFinite(v)) return '—'
  if (v === 0) return '0'
  const e = Math.floor(Math.log10(Math.abs(v)))
  if (e >= -2 && e <= 3) return Number(v.toPrecision(digits + 1)).toString()
  const sup = String(e).replace(/-/g, '⁻').replace(/\d/g, (d) => '⁰¹²³⁴⁵⁶⁷⁸⁹'[Number(d)])
  return `${(v / 10 ** e).toFixed(digits)} × 10${sup}`
}
/** How the case agrees, in a few words: exact agreement, or within a stated tolerance for a known difference. */
export const agreement = (c: IndexRow) => (c.rtol.why ? `within ${Number((c.rtol.value * 100).toPrecision(2))}%${c.rtol.quantities ? ` (${c.rtol.quantities.join(', ')})` : ''}` : sci(c.worst))
